// n8n Code düğümü: "Sayfa Listesini Oluştur" (Run Once for All Items)
// Girdi : "Sayfa 1'i Çek" düğümünün çıktısı → json.html (1. sayfanın HTML'i)
// Çıktı : taranacak her sayfa için bir öğe → { sayfa, url }
//
// Site ?page=N ile sayfalanıyor ve sayfalama çubuğu son sayfayı da gösteriyor
// (1 … 10 … 19 20). Sayfa linklerindeki en büyük N = son sayfa. Sayfa sayısı
// değişirse akış kendiliğinden uyum sağlar; sabit "20" yazılmadı.
const ayar = $('Ayarlar').first().json;
const html = String($input.first().json.html || '');

const sayfaNolari = [...html.matchAll(/[?&]page=(\d+)/g)].map((m) => Number(m[1]));
const sonSayfa = Math.min(Math.max(1, ...sayfaNolari), Number(ayar.max_sayfa) || 50);

const sayfalar = [];
for (let sayfa = 1; sayfa <= sonSayfa; sayfa++) {
  sayfalar.push({ json: { sayfa, url: `${ayar.taban_url}?page=${sayfa}` } });
}
return sayfalar;

// n8n Code düğümü: "Ürünleri Ayrıştır" (Run Once for All Items)
// Girdi : "Tüm Sayfaları Çek" çıktısı → sayfa başına bir öğe (json.html ya da json.error)
// Çıktı : TEK özet öğe → { tarih, urun_sayisi, saglikli, urunler: [...], ... }
//
// Neden tek özet öğe? Hiç ürün çıkmazsa n8n 0 öğeyle dalı sessizce bitirir ve
// yürütme "başarılı" görünür. Özet öğe her zaman üretilir; ardından gelen IF
// düğümü `saglikli` alanına bakıp hata dalına yönlendirir.
const ayar = $('Ayarlar').first().json;
const sayfaListesi = $('Sayfa Listesini Oluştur').all();
const sayfaCiktilari = $input.all();

const simdi = new Date();
// İstanbul saatine göre YYYY-MM-DD ("sv-SE" biçimi ISO tarih verir)
const tarih = new Intl.DateTimeFormat('sv-SE', { timeZone: 'Europe/Istanbul' }).format(simdi);

const htmlCoz = (s) => String(s)
  .replace(/&quot;/g, '"').replace(/&#0?39;/g, "'").replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>').replace(/&amp;/g, '&').trim();

// "$1,139.54" → 1139.54 : para simgesi ve binlik ayırıcı virgül temizlenir.
// (Şablondaki parseFloat("$1,139.54".replace("$","")) gibi bir yaklaşım 1 döndürürdü.)
const fiyataCevir = (metin) => Number(String(metin || '').replace(/[^0-9.]/g, '')) || NaN;

const urunler = new Map(); // link → ürün; aynı ürün iki sayfada görünürse tekrar sayılmaz
const hataliSayfalar = [];
const bosSayfalar = [];
let hataliKart = 0;

sayfaCiktilari.forEach((oge, i) => {
  const sayfa = sayfaListesi[i]?.json.sayfa ?? i + 1;
  if (oge.json.error) {
    hataliSayfalar.push(sayfa);
    return;
  }
  const kartlar = String(oge.json.html || '').split('class="card thumbnail"').slice(1);
  if (kartlar.length === 0) {
    bosSayfalar.push(sayfa);
    return;
  }
  for (const kart of kartlar) {
    const link = (kart.match(/href="([^"]*\/product\/(\d+))"/) || [])[1];
    const ad = (kart.match(/class="title"[^>]*title="([^"]*)"/) || [])[1];
    const fiyat = fiyataCevir((kart.match(/itemprop="price"[^>]*>([^<]*)</) || [])[1]);
    const yorum = parseInt((kart.match(/itemprop="reviewCount"[^>]*>([^<]*)</) || [])[1], 10);
    if (!link || !ad || !Number.isFinite(fiyat)) {
      hataliKart++;
      continue;
    }
    const tamLink = link.startsWith('http') ? link : ayar.site_kok.replace(/\/$/, '') + link;
    urunler.set(tamLink, {
      urun_id: Number(link.match(/(\d+)$/)[1]),
      ad: htmlCoz(ad),
      fiyat,
      yorum_sayisi: Number.isFinite(yorum) ? yorum : 0,
      link: tamLink,
      sayfa,
    });
  }
});

const beklenenSayfa = sayfaListesi.length;
const eksikSayfa = beklenenSayfa - sayfaCiktilari.length;
const sorunlar = [];
if (urunler.size === 0) sorunlar.push('hiç ürün bulunamadı');
if (hataliSayfalar.length) sorunlar.push(`açılamayan sayfa(lar): ${hataliSayfalar.join(', ')}`);
if (bosSayfalar.length) sorunlar.push(`ürünsüz sayfa(lar): ${bosSayfalar.join(', ')}`);
if (eksikSayfa > 0) sorunlar.push(`${eksikSayfa} sayfanın yanıtı eksik`);
if (hataliKart > 0) sorunlar.push(`${hataliKart} ürün kartı ayrıştırılamadı`);

return [{
  json: {
    tarih,
    calisma_zamani: simdi.toISOString(),
    beklenen_sayfa: beklenenSayfa,
    taranan_sayfa: sayfaCiktilari.length - hataliSayfalar.length,
    urun_sayisi: urunler.size,
    // Eksik tarama "sağlıklı" sayılmaz: yarım veriyle karşılaştırma yapılırsa
    // taranamayan ürünler yanlışlıkla "kaldırıldı" diye raporlanırdı.
    saglikli: sorunlar.length === 0,
    sorunlar,
    urunler: [...urunler.values()],
  },
}];

// n8n Code düğümü: "Değişiklikleri Bul" (Run Once for All Items)
// Girdi : "Son Durumu Oku" (Google Sheets → son_durum sekmesi; ürün başına bir satır).
//         Sekme boşsa (ilk çalışma) düğümün "Always Output Data" ayarı tek boş öğe verir.
// Çıktı : TEK öğe → yeni / fiyatı değişen / kaldırılan ürünler + tablolara yazılacak satırlar.
//
// Anahtar = ürün linki (/product/{id}). Ürün adı anahtar olamaz: sitede aynı
// ada sahip farklı konfigürasyonlu laptoplar var.
const tarama = $('Ürünleri Ayrıştır').first().json;
const onceki = $input.all().map((o) => o.json).filter((r) => r && r.link);
const ilkCalisma = onceki.length === 0;

// Sheets yerel ayarı Türkçe ise fiyat "1.139,54" gelebilir; iki biçim de sayıya çevrilir.
const sayiyaCevir = (v) => {
  if (typeof v === 'number') return v;
  const s = String(v ?? '').trim().replace(/[^0-9.,-]/g, '');
  if (/^-?\d{1,3}(\.\d{3})*,\d+$/.test(s) || /^-?\d+,\d+$/.test(s)) {
    return Number(s.replace(/\./g, '').replace(',', '.'));
  }
  return Number(s.replace(/,/g, ''));
};

const oncekiHarita = new Map(onceki.map((r) => [String(r.link), r]));
const simdikiHarita = new Map(tarama.urunler.map((u) => [u.link, u]));

const yeni = [];
const degisen = [];
for (const u of tarama.urunler) {
  const o = oncekiHarita.get(u.link);
  if (!o || o.durum === 'kaldirildi') {
    if (!ilkCalisma) yeni.push(u); // ilk çalışmada her şey "yeni" sayılıp alarm yağdırılmaz
    continue;
  }
  const eski = sayiyaCevir(o.fiyat);
  if (Number.isFinite(eski) && Math.abs(eski - u.fiyat) >= 0.005) {
    degisen.push({
      ...u,
      eski_fiyat: eski,
      fark: Number((u.fiyat - eski).toFixed(2)),
      yuzde: eski ? Number((((u.fiyat - eski) / eski) * 100).toFixed(2)) : null,
    });
  }
}
const kaldirilan = onceki.filter((o) => o.durum !== 'kaldirildi' && !simdikiHarita.has(String(o.link)));

const gecmisSatirlari = tarama.urunler.map((u) => ({
  tarih: tarama.tarih,
  calisma_zamani: tarama.calisma_zamani,
  urun_id: u.urun_id,
  ad: u.ad,
  fiyat: u.fiyat,
  yorum_sayisi: u.yorum_sayisi,
  link: u.link,
}));

const sonDurumSatirlari = [
  ...tarama.urunler.map((u) => ({
    link: u.link,
    urun_id: u.urun_id,
    ad: u.ad,
    fiyat: u.fiyat,
    yorum_sayisi: u.yorum_sayisi,
    ilk_gorulme: oncekiHarita.get(u.link)?.ilk_gorulme || tarama.tarih,
    son_gorulme: tarama.tarih,
    durum: 'aktif',
  })),
  // Kaldırılan ürün bir kez raporlanır, sonra "kaldirildi" olarak işaretlenir.
  // Sheets okuması her satıra `row_number` ekliyor; o alan tabloya sütun olarak geri yazılmasın.
  ...kaldirilan.map(({ row_number, ...o }) => ({ ...o, durum: 'kaldirildi' })),
];

return [{
  json: {
    tarih: tarama.tarih,
    urun_sayisi: tarama.urun_sayisi,
    ilk_calisma: ilkCalisma,
    yeni,
    degisen,
    kaldirilan,
    degisiklik_var: yeni.length + degisen.length + kaldirilan.length > 0,
    bildirim_gerekli: ilkCalisma || yeni.length + degisen.length + kaldirilan.length > 0,
    gecmis_satirlari: gecmisSatirlari,
    son_durum_satirlari: sonDurumSatirlari,
  },
}];

// n8n Code düğümü: "Bildirim E-postasını Hazırla" (Run Once for All Items)
// Girdi : "Değişiklikleri Bul" özeti. Çıktı: { konu, html } → "Send Email" düğümü.
const d = $input.first().json;
const para = (n) => `$${Number(n).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
const kacis = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const link = (u) => `<a href="${kacis(u.link)}">${kacis(u.ad)}</a>`;

const tablo = (baslik, satirlar, basliklar) => (satirlar.length === 0 ? '' : `
  <h3>${baslik} (${satirlar.length})</h3>
  <table cellpadding="6" style="border-collapse:collapse;font-size:14px">
    <tr style="background:#f1f3f5">${basliklar.map((b) => `<th align="left">${b}</th>`).join('')}</tr>
    ${satirlar.join('\n')}
  </table>`);

// Önce en büyük değişimler
const degisen = [...d.degisen].sort((a, b) => Math.abs(b.yuzde) - Math.abs(a.yuzde));

const govde = d.ilk_calisma
  ? `<p>İlk çalışma: <b>${d.urun_sayisi}</b> ürün referans olarak kaydedildi. Bundan sonraki
     çalışmalarda yalnızca fiyatı değişen, yeni çıkan ve kaldırılan ürünler bildirilecek.</p>`
  : [
    tablo('Fiyatı değişen ürünler', degisen.map((u) => `<tr><td>${link(u)}</td><td>${para(u.eski_fiyat)}</td>
      <td>${para(u.fiyat)}</td><td style="color:${u.fark < 0 ? '#2b8a3e' : '#c92a2a'}">${u.fark < 0 ? '▼' : '▲'}
      ${u.yuzde}%</td></tr>`), ['Ürün', 'Eski fiyat', 'Yeni fiyat', 'Değişim']),
    tablo('Yeni çıkan ürünler', d.yeni.map((u) => `<tr><td>${link(u)}</td><td>${para(u.fiyat)}</td>
      <td>${u.yorum_sayisi}</td></tr>`), ['Ürün', 'Fiyat', 'Yorum']),
    tablo('Listeden kalkan ürünler', d.kaldirilan.map((u) => `<tr><td>${link(u)}</td>
      <td>${para(u.fiyat)}</td></tr>`), ['Ürün', 'Son bilinen fiyat']),
  ].join('');

const ozet = d.ilk_calisma
  ? 'ilk çalışma, referans kaydedildi'
  : `${d.degisen.length} fiyat değişikliği, ${d.yeni.length} yeni, ${d.kaldirilan.length} kaldırılan`;

return [{
  json: {
    konu: `Laptop fiyat takibi ${d.tarih}: ${ozet}`,
    html: `<div style="font-family:Segoe UI,Arial,sans-serif">
      <h2 style="margin:0 0 8px">Laptop fiyat takibi — ${d.tarih}</h2>
      <p style="color:#555">Taranan ürün: ${d.urun_sayisi} · Kaynak: webscraper.io test sitesi (tüm sayfalar)</p>
      ${govde}
    </div>`,
  },
}];

// n8n Code düğümü: "Hata Mesajını Hazırla" (Run Once for All Items)
// İki kaynaktan beslenir:
//   1) "Sayfa 1'i Çek" hata çıkışı  → json.error (site açılmadı / zaman aşımı / 5xx)
//   2) "Tarama sağlıklı mı?" false  → "Ürünleri Ayrıştır" özeti (hiç ürün yok, eksik sayfa...)
const girdi = $input.first().json;
const tarih = new Intl.DateTimeFormat('sv-SE', { timeZone: 'Europe/Istanbul' }).format(new Date());

let neden;
if (girdi.error) {
  const e = girdi.error;
  neden = `Site açılamadı: ${e.message || e.description || JSON.stringify(e).slice(0, 300)}`;
} else {
  neden = `Tarama sağlıksız (${girdi.urun_sayisi ?? 0} ürün, ${girdi.taranan_sayfa ?? 0}/${girdi.beklenen_sayfa ?? '?'} sayfa): `
    + ((girdi.sorunlar || []).join('; ') || 'bilinmeyen sorun');
}

return [{
  json: {
    hata_mesaji: neden,
    konu: `[HATA] Laptop fiyat takibi ${tarih}: çalışma başarısız`,
    html: `<div style="font-family:Segoe UI,Arial,sans-serif">
      <h2 style="color:#c92a2a;margin:0 0 8px">Laptop fiyat takibi başarısız oldu</h2>
      <p><b>Neden:</b> ${String(neden).replace(/</g, '&lt;')}</p>
      <p>Bu çalışmada tablolar güncellenmedi ve değişiklik karşılaştırması yapılmadı
      (yarım veriyle yanlış "kaldırıldı" alarmı üretmemek için).</p>
      <p>Kaynak: https://webscraper.io/test-sites/e-commerce/static/computers/laptops</p>
    </div>`,
  },
}];
